Ext.define('bcp.view.IbbrRoomTreeWindowViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.ibbrroomtreewindow',

    expandAllTree: function (button, e, eOpts) {
        Ext.suspendLayouts();
        var tree = this.lookupReference('tree');
        //tree.expandAll();
        var root = tree.getRootNode();
        root.expandChildren(false);
        Ext.resumeLayouts(false);
    },

    collapseAllTree: function (button, e, eOpts) {
        var tree = this.lookupReference('tree');
        var root = tree.getRootNode();
        root.collapseChildren(true);
    },

    onFilterTextChange: function (field, newValue, oldValue, eOpts) {
        if (newValue !== null) {
            var tree = this.lookupReference('tree'),
                v;
            if (newValue !== '') {
                try {
                    v = new RegExp(newValue, 'i');
                    tree.store.clearFilter();
                    tree.store.filter({
                        filterFn: function (node) {
                            var children = node.childNodes,
                                len = children && children.length,
                                visible = node.isLeaf()
                                    ? v.test(node.get('text')) ||
                                      v.test(node.get('roomDescription'))
                                    : false,
                                i;

                            for (
                                i = 0;
                                i < len &&
                                !(visible = children[i].get('visible'));
                                i++
                            );

                            if (!visible) {
                                visible =
                                    v.test(node.get('text')) ||
                                    v.test(node.get('roomDescription'));
                            }

                            return visible;
                        },
                        id: 'roomTreeTextFilter1'
                    });
                } catch (e) {
                    //catch node list exception
                }
            } else {
                tree.store.clearFilter();
            }
        }
    },

    onSelect: function (button, e, eOpts) {
        var tree = this.lookupReference('tree');
        var selectedItem = tree.getSelection();
        if (selectedItem.length > 0) {
            if (selectedItem[0].childNodes.length > 0) {
                Ext.Msg.alert(
                    'Warning',
                    'please select a room instead of site, building or floor.'
                );
            } else {
                this.fireViewEvent('applyIbbr', this, selectedItem[0].data);
            }
        } else {
            Ext.Msg.alert('Warning', 'please select a room.');
        }
    }
});
